// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address caller, uint256 v) internal {
        vm.deal(address(c), VALUE_CAP);
        uint cBalBefore = address(c).balance;
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        uint callerBalBefore = address(this).balance;
        bool reverted;
        try c.withdraw(v) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint cBalAfter = address(c).balance;
        uint256 depositsAfter;
        try c.depositsCount() returns (uint256 __r) { depositsAfter = __r; } catch { return; }
        uint callerBalAfter = address(this).balance;
        assertTrue((reverted == (v > cBalBefore)) &&
            (reverted || (cBalAfter == cBalBefore - v && callerBalAfter == callerBalBefore + v)) &&
            (!reverted || (cBalAfter == cBalBefore && callerBalAfter == callerBalBefore)) &&
            depositsAfter == depositsBefore);
    }

    function testFuzz_run(address caller, uint256 v) public {
        vm.assume(caller.code.length == 0 && uint160(caller) > 0xffff && caller != address(this) && caller != address(c) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(caller, v);
    }

    receive() external payable {}
}
